from heapq import heappush, heappop

def merge_and_sort(numbers):
    """
    Merges nums (which is a list of pairs) which represent element values and their indices into a list of sorted elements.
    Replaces the old nums with a new list of sorted elements to leave only sorted values in the original list.
    """
    sorted_nums = []

    while numbers:
        try:
            num_a, num_a_i = heappop(numbers)
            if sorted_nums and sorted_nums[0] < num_a:
                heappush(sorted_nums, -heappop(sorted_nums))
            heappush(sorted_nums, (-num_a, -num_a_i))
        except IndexError:
            break

    if len(sorted_nums) < 2:
        return [-1, -1]
    return list(map(lambda t: max(t[0], 0), sorted_nums))

def solve(n, nums):
    """
    Returns the minimum number of operations required to sort nums.
    """
    heap = []
    for i, num in enumerate(nums):
        heappush(heap, (10**6 + num, i))

    # Push n-1 elements other than maximum value
    heappush(heap, (10**6 + -1, -1))
    total_operations = 0
    previous = -1
    visited = {0}
    while heap:
        current, current_i = heappop(heap)

        # Ensure current value is a maximum
        if current < 10**6 + -1:
            heappush(heap, (10**6 + -1, -1))
            continue

        if current == -1:
            current = 10**6

        for a_i in range(current_i - 1, -1, -1):
            if n - a_i <= current:
                a, a_i_v = i, a_i
                total_operations += 1
                break
        else:
            total_operations += 1

        a_i_v = i
        while list(sorted_nums) and sorted_nums[0] < a_i_v:
            a, a_i_v = heappop(sorted_nums)
            total_operations += 1

    return total_operations

