# Function to calculate the modified XOR operation for a segment
def modified_xor(segment):
    return reduce(lambda x, y: x * (y >> 1) + y % 2, segment, 0)

# Extended Euclidean Algorithm with Euclid's Algorithm for modular inversion
def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, y, x = extended_gcd(b % a, a)
        return (g, x - (b // a) * y, y)

# Euler's Totient Function
def euler_totient(n):
    result = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
    if n > 1:
        result -= result // n
    return result

# Calculate the Score
def calculate_score(arr):
    n = len(arr)
    mod = 998244353
    den = euler_totient(31) * euler_totient(31) ** 3
