To address the problem of counting Tsetso subarrays within a given range, we can use a dynamic programming approach. The idea is to maintain two sequences: one for the maximum values to the left of each position and one for the maximum values to the right of each position. By iterating through the array, we can determine whether each subarray is Tsetso based on these sequences.

Here's the Python code to solve this problem:

```python
def count_tsetso_queries(N: int, Q: int) -> None:
    arr = list(map(int, input().split()))
    max_left = [-1] * N
    max_right = [N] * N

    # Fill max_left sequence
    for i in range(1, N):
        if arr[i] > arr[max_left[i]]:
            max_left[i] = i

    # Fill max_right sequence
    for i in range(N - 2, -1, -1):
        if arr[i] > arr[max_right[i]]:
            max_right[i] = i

    ret = []
    for _ in range(Q):
        l, r = map(int, input().split())
        l -= 1
        r -= 1
        if l >= 0 and r >= 0:
            # Check if the segment is a Tsetso subarray
            if arr[l] * arr[r] == arr[max_left[r]]:
                ret.append(1)
            else:
                ret.append(0)
        else:
            # If one of the ends is out of bounds
            if l > -1:
                ret.append(arr[l] * arr[max_right[l]] > arr[-1] * arr[max_right[-1]] and arr[l] * arr[max_left[l]] > arr[-1] * arr[-1])
            elif r > -1:
                ret.append(arr[r] * arr[max_left[r]] > arr[0] * arr[max_left[0]] and arr[r] * arr[max_left[r]] > arr[-1] * arr[-1])
            else:
                ret.append(0)

    for ans in ret:
        print(ans)

# Example usage:
count_tsetso_queries(7, 3)
