    dp_cal, dp_trunc = defaultdict(solvemult), defaultdict(solvemult)

    for i in range(perm_len // 2 + 1):
        for j in range(i, perm_len - i):

            bucket = bit_tools(j+1, j-i-1, 2)

            rel_bucket_sum = sum(2**x for x in range(i+1, perm_len - 2*j))

            com_set_size = bin(rel_bucket_sum).count('1') 

            dp_cal[j, rel_bucket_sum] = bin(rel_bucket_sum)[-com_set_size:].count('1') 

            rem = (j - i + 1)

            eval_mod = bin(bucket)[::-1][:-log2(rem)-1]

            dp_trunc.add(eval_mod)

    count = 0

