from collections import defaultdict

def get_lattice_points(n, graph, vertex):
    points = set()
    queue = [(vertex, [vertex])]
    while queue:
        vertex, path = queue.pop(0)
        for next_vertex in sorted(graph[vertex]):
            if next_vertex not in path:
                points.add(abs(next_vertex - vertex))
                queue.append((next_vertex, path + [next_vertex]))
    return points

def solve(n, k, graph):
    if k == 1:
        return sum(graph[vertex] for vertex in range(n)) // 2
    points = get_lattice_points(n, graph, 1)
    lcm = 1
    for point in points:
        lcm = lcm * abs(point)
    return int(sqrt(lcm / n)) // k

