import sys
from typing import List

def share_point(pt1, pt2):
    return (pt1[0] == pt2[0] or pt1[1] == pt2[1])

def test_ships(c1, c2, c3):
    return not (share_point(c1, c2) and share_point(c2, c3) and share_point(c3, c1))

def min_columns(points: List[List[int]]) -> int:
    # Pair the points to build 3 columns per pair
    points_pairs: List[List[List[int]]] = [[[], []], [[ ], []], [[ ], []], [[ ], []]]

    for i, pt1 in enumerate(points):
        for j, pt2 in enumerate(points):
            if i < j and test_ships(pt1, pt2, points[(i + 1) % 4]):
                points_pairs[i // 2][j % 2].append(pt1)
                points_pairs[i // 2][(j + 1) % 2].append(pt2)

    # Sift pairs into a single group
    groups = [union_find(cur_pair) for cur_pair in points_pairs]

    # Count conflicts between groups
    conflicts = 0
    for i in range(len(groups)):
        for j in range(i + 1, len(groups)):
            if test_ships(*groups[i].get_points(), *groups[j].get_points()):
                conflicts += 1

    return conflicts // 3 + 1

def union_find(points: List[List[int]]):
    groups = [i for i in range(len(points))]
    def find(x):
        if x != groups[x]:
            groups[x] = find(groups[x])
        return groups[x]

    def union(x, y):
        groups[find(x)] = find(y)

    for pt1, pt2 in combinations(points, 2):
        union(pt1, pt2)

    return groups

