class BipartiteGraph:
    def __init__(self, n1, n2, m):
        self.n1 = n1
        self.n2 = n2
        self.m = m
        self.next_edge = {(0, i): i + self.m + 1 for i in range(self.m)}
        for i in range(self.m):
            self.next_edge[(i, self.m + i)] = i
            self.next_edge[(i, self.m + i + self.m)] = self.m + i + 1

        self.edge_colors = [0] * self.m

        self.red_edges = []
        self.blue_edges = []


    def add_edge(self, x, y):
        x, y = min(x, y), max(x, y)

        cycle = set()

        while True:
            mask = self.edges_gen[(x, y)] & self.edges_gen[self.edge_colors[y]]
            if mask < self.next_edge[(x, y)]:
                x, y = y, mask
                break
            else:
                cycle.add(x)
                x, y = x, self.edges_gen[(x, y)]

        self.red_edges.append((x, y))
        self.blue_edges.append((x, y))

        old_mask = self.edges_gen[(x, y)]      
        self.edges_gen[y] |= old_mask

        for old_x, new_x in [(x, set()), (set(), y)]:            
            old_mask |= old_x
            new_mask = self.edges_gen[new_x] ^ self.edges_gen[(old_x, new_x)]

            if new_mask < self.next_edge[(old_x, new_x)]:
                _ = self.edges_gen[y], y, new_x
                _ = new_mask
                break

        return old_mask 


