from collections import deque

def is_tsetso_subarray(arr, l, r):
    max_val = max(arr[l-1:r])
    pairs = deque()
    pairs.append((max_val, 1))

    for i in range(r-1, l-1, -1):
        value = arr[i]
        if value > max_val:
            max_val = value
            pairs.append((max_val, 1))
        elif i > l-1:
            pairs.popleft()
            pairs.appendleft((max_val, 1))

        if value > pairs[0][0]:
            pairs.popleft()
            pairs.append((max_val, value))
        if value < pairs[0][0]:
            pairs.popleft()
            pairs.appendleft((max_val, value))

        if len(pairs) > 2 and value > pairs[0][0]:
            return True
        if len(pairs) > 0 and value > pairs[-1][0]:
            return True

    return False

def solve(n, q, tests):
    for i in range(tests):
        arr = list(map(int, input().split()))
        queries = deque()
        for j in range(q):
            l, r = map(int, input().split())
            queries.append((l, r))

        ans = []
        for l, r in queries:
            if is_tsetso_subarray(arr, l, r):
                ans.append(1)
            else:
                ans.append(0)

        print("Case #{}: {}".format(i+1, " ".join(map(str, ans))))

T = int(input())
solve(T, 5, T)
