import sys

def partition_permutations(array):
    occurrences = {}
    for num in array:
        occurrences[num] = occurrences.get(num, 0) + 1

    # Count the number of elements that do not belong to a partition
    leftover = sum(occurrences[num] for num in occurrences if occurrences[num] % 2 != 0)

    # Compare with the minimum number of modifications needed for partitions
    return min(leftover, len(array) - leftover)

